import { makeExecutableSchema } from "@graphql-tools/schema";
import { graphql } from "graphql";
const authors = [{ id: "a1", name: "Ursula K. Le Guin" }];
const books = [{ id: "b1", title: "The Dispossessed", authorId: "a1" }];
const typeDefs = `
  type Author { id: ID!  name: String! }
  type Book { id: ID!  title: String!  author: Author! }
  type Query { book(id: ID!): Book }
`;
const resolvers = {
  Query: {
    book: (_parent, { id }) => books.find((b) => b.id === id) ?? null,
  },
  Book: { // title uses the default resolver (book.title)
    author: (book) => authors.find((a) => a.id === book.authorId),
  },
};
const schema = makeExecutableSchema({ typeDefs, resolvers });
const res = await graphql({ schema, source: '{ book(id: "b1") { title author { name } } }' });
console.log(JSON.stringify(res.data));
// {"book":{"title":"The Dispossessed","author":{"name":"Ursula K. Le Guin"}}}

