import DataLoader from "dataloader";
const db = { calls: 0,
  async authorsByIds(ids) { this.calls++; return ids.map((id) => ({ id, name: "Author " + id })); },
};
function createContext() {
  return {
    authorLoader: new DataLoader(async (ids) => {
      const rows = await db.authorsByIds(ids);
      const byId = new Map(rows.map((r) => [r.id, r]));
      return ids.map((id) => byId.get(id) ?? null); // same order as ids
    }),
  };
}
const resolvers = { Book: { author: (book, _a, ctx) => ctx.authorLoader.load(book.authorId) } };

const ctx = createContext();
const books = [{ authorId: "a1" }, { authorId: "a2" }, { authorId: "a1" }];
const authors = await Promise.all(books.map((b) => resolvers.Book.author(b, {}, ctx)));
console.log(authors.map((a) => a.name), "db calls:", db.calls);
// [ 'Author a1', 'Author a2', 'Author a1' ] db calls: 1

