import { makeExecutableSchema } from "@graphql-tools/schema";
import { parse, subscribe } from "graphql";
async function* ticks() { for (let i = 1; i <= 3; i++) yield { tick: i }; }
const schema = makeExecutableSchema({
  typeDefs: `type Query { ok: Boolean }  type Subscription { tick: Int! }`,
  resolvers: { Subscription: { tick: { subscribe: () => ticks() } } },
});
const stream = await subscribe({ schema, document: parse("subscription { tick }") });
for await (const result of stream) console.log(JSON.stringify(result.data));
// {"tick":1}
// {"tick":2}
// {"tick":3}

