import { buildSchema, parse, validate, execute, visit, Kind } from "graphql";
const schema = buildSchema(`type Query { a: Int  b: Int }`);
const document = parse("query Q { a b ...F } fragment F on Query { a }");

const fields = [];
visit(document, { Field: (node) => { fields.push(node.name.value); } });
console.log(fields); // [ 'a', 'b', 'a' ]

console.log(validate(schema, document).length); // 0 -> valid
const result = await execute({
  schema, document,
  rootValue: { a: () => { console.log("resolve a"); return 1; }, b: 2 },
});
// "resolve a" is printed once: same-named fields are merged
console.log(JSON.stringify(result.data)); // {"a":1,"b":2}
console.log(document.definitions[0].kind === Kind.OPERATION_DEFINITION); // true

import { buildSchema, parse, validate, GraphQLError } from "graphql";

function depthLimit(max) {
  return (context) => {
    let depth = 0;
    return {
      SelectionSet: {
        enter(node) {
          if (++depth === max + 1) context.reportError(
            new GraphQLError(`Query depth exceeds ${max}`, { nodes: [node] }));
        },
        leave() { depth--; },
      },
    };
  };
}
const schema = buildSchema(`type User { name: String  friends: [User!]! }
  type Query { me: User }`);
const deep = parse("{ me { friends { friends { friends { name } } } } }");
console.log(validate(schema, deep, [depthLimit(3)]).map((e) => e.message));
// [ 'Query depth exceeds 3' ]

# Client query against the supergraph
query ProductPage($upc: ID!) {
  product(upc: $upc) {
    name            # resolved by products subgraph
    price           # resolved by products subgraph
    reviews {       # resolved by reviews subgraph
      body
    }
  }
}

